/* =====================================================================
   Griffin Museum — Mobile Companion i18n
   Ported from the kiosk translation system (find-my-way.html):
     - same five languages (English, Español, Polski, العربية, Français)
     - same DOM-walking model: each text node's English original is
       remembered, looked up in the dictionary, and swapped in place;
       strings absent from the dictionary (e.g. exhibit names) stay in
       English automatically.
     - placeholder / aria-label / title attributes translated too.
     - a MutationObserver keeps dynamically rendered content translated,
       synchronously, before paint (no flicker).
     - persistence in localStorage; Arabic switches document dir to rtl.
   Translations shared with the kiosk are reused verbatim; only mobile-
   specific wording is added on top. Exhibit names are never translated.
   ===================================================================== */
(function () {
  "use strict";

  var STORE = "griffin.wayfinding.lang.v1";

  var lang = "en";
  try { lang = localStorage.getItem(STORE) || "en"; } catch (e) {}
  if (!T[lang] && lang !== "en") lang = "en";

  function dict() { return T[lang] || null; }

  /* ---- phrase lookup, incl. generated patterns ---- */
  function lookup(text) {
    var d = dict();
    if (!d) return undefined;
    if (Object.prototype.hasOwnProperty.call(d, text)) return d[text];

    var m;
    // kiosk-inherited numeric patterns
    m = /^Floor\s+(\d+)\s+of\s+(\d+)$/.exec(text);
    if (m) return d["Floor"] + " " + m[1] + " " + d["of"] + " " + m[2];
    m = /^(\d+)\s*min\s+walk$/.exec(text);
    if (m) return m[1] + " " + d["min"] + " " + d["walk"];
    m = /^(\d+)\s*min$/.exec(text);
    if (m) return m[1] + " " + d["min"];
    m = /^(\d+)\s+locations?$/.exec(text);
    if (m) return m[1] + " " + d[+m[1] === 1 ? "location" : "locations"];
    // mobile progress + floor patterns
    m = /^(\d+)\s+of\s+(\d+)\s+exhibits$/.exec(text);
    if (m) return m[1] + " " + d["of"] + " " + m[2] + " " + d["exhibits"];
    m = /^(\d+)%\s+complete$/.exec(text);
    if (m) return m[1] + "% " + d["complete"];
    m = /^Level\s+(\d+)$/.exec(text);
    if (m) return d["Level"] + " " + m[1];

    // case-insensitive fallback so ALL-CAPS labels ("PARKING") match,
    // keeping the original capitalisation style.
    var ci = ciIndex();
    var hit = ci[text.toLowerCase()];
    if (hit !== undefined) {
      if (text === text.toUpperCase() && /[A-Za-z]/.test(text)) return hit.toUpperCase();
      return hit;
    }
    return undefined;
  }

  var CI = {};
  function ciIndex() {
    if (CI[lang]) return CI[lang];
    var d = dict(), out = {};
    if (d) for (var k in d) if (Object.prototype.hasOwnProperty.call(d, k)) out[k.toLowerCase()] = d[k];
    CI[lang] = out;
    return out;
  }

  /* ---- DOM translation, remembering the English original ---- */
  var ORIG = new WeakMap();
  var SKIP = { SCRIPT: 1, STYLE: 1, NOSCRIPT: 1, CANVAS: 1 };  // NOT svg: map labels like "You Are Here" must translate (matches kiosk)

  function walk(root) {
    if (!root) return;
    var it = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode: function (n) {
        var p = n.parentNode;
        if (!p || SKIP[p.nodeName]) return NodeFilter.FILTER_REJECT;
        if (!n.nodeValue || !n.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    var n, list = [];
    while ((n = it.nextNode())) list.push(n);
    list.forEach(applyText);

    var els = root.querySelectorAll ? root.querySelectorAll("[placeholder],[aria-label],[title]") : [];
    Array.prototype.forEach.call(els, function (el) {
      ["placeholder", "aria-label", "title"].forEach(function (a) {
        if (!el.hasAttribute(a)) return;
        var key = "__en_" + a;
        if (el[key] === undefined) el[key] = el.getAttribute(a);
        var src = el[key], out = lookup(String(src).trim());
        el.setAttribute(a, out === undefined ? src : out);
      });
    });
  }

  function applyText(node) {
    if (!ORIG.has(node)) ORIG.set(node, node.nodeValue);
    var src = ORIG.get(node);
    var key = src.trim();
    if (!key) return;
    var out = lookup(key);
    if (out === undefined) { if (node.nodeValue !== src) node.nodeValue = src; return; }
    var lead = src.match(/^\s*/)[0], trail = src.match(/\s*$/)[0];
    node.nodeValue = lead + out + trail;
  }

  /* ---- language menu, built for every .lang-select button ---- */
  function buildMenus() {
    Array.prototype.forEach.call(document.querySelectorAll(".lang-select"), function (btn) {
      if (btn.__langWired) return;
      btn.__langWired = true;

      var host = btn.parentNode;
      if (host && getComputedStyle(host).position === "static") host.style.position = "relative";

      var menu = document.createElement("div");
      menu.className = "lang-menu mobile-lang-menu";
      menu.innerHTML = LANGS.map(function (l) {
        return '<button type="button" data-lang="' + l.code + '">' + l.native +
               ' <span>' + (l.code === lang ? "\u2713" : "") + "</span></button>";
      }).join("");
      (host || btn).appendChild(menu);

      btn.addEventListener("click", function (e) {
        e.stopPropagation();
        var open = menu.classList.contains("open");
        document.querySelectorAll(".lang-menu.open").forEach(function (m) { m.classList.remove("open"); });
        if (!open) menu.classList.add("open");
      });
      menu.addEventListener("click", function (e) {
        var b = e.target.closest("button[data-lang]");
        if (!b) return;
        e.stopPropagation();
        setLang(b.getAttribute("data-lang"));
        menu.classList.remove("open");
      });
    });
    document.addEventListener("click", function () {
      document.querySelectorAll(".lang-menu.open").forEach(function (m) { m.classList.remove("open"); });
    });
  }

  function refreshChecks() {
    document.querySelectorAll(".mobile-lang-menu button[data-lang]").forEach(function (b) {
      var s = b.querySelector("span");
      if (s) s.textContent = b.getAttribute("data-lang") === lang ? "\u2713" : "";
    });
  }

  function setLang(code) {
    lang = (T[code] || code === "en") ? code : "en";
    CI = {};
    try { localStorage.setItem(STORE, lang); } catch (e) {}
    document.documentElement.setAttribute("lang", lang);
    document.documentElement.setAttribute("dir", lang === "ar" ? "rtl" : "ltr");
    document.body.classList.toggle("lang-rtl", lang === "ar");
    walk(document.body);
    refreshChecks();
  }

  /* ---- keep dynamically rendered content translated ---- */
  function start() {
    buildMenus();
    setLang(lang);
    var obs = new MutationObserver(function (muts) {
      if (lang === "en") return;
      for (var i = 0; i < muts.length; i++) {
        var m = muts[i];
        if (m.type !== "childList" || !m.addedNodes.length) continue;
        for (var j = 0; j < m.addedNodes.length; j++) {
          var n = m.addedNodes[j];
          if (n.nodeType === 3) applyText(n);
          else if (n.nodeType === 1) walk(n);
        }
      }
    });
    obs.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start);
  else start();

  // t(): translate a bare string for contexts the DOM walker can't reach
  // (window.alert, and dynamically-assigned placeholders).
  function t(s) { var o = lookup(String(s)); return o === undefined ? s : o; }

  window.MobileI18n = { set: setLang, get: function () { return lang; }, t: t, languages: LANGS };
})();
